  "candidates": [
    {
      "candidate_id": "955ec5dd8a19fdbec4335b20",
      "title": "Breaking AI Memory Limits with CXL Memory Pooling",
      "summary": "Samsung's evaluation of CXL memory pooling (CMM-D modules through a CXL switch, 1TB pool) for offloading LLM KV cache, reporting near-DRAM performance (approximately 92% of DRAM at 8 GPUs) and stable throughput under growing KV cache demands where DRAM degraded.",
      "rule_score": 93.6,
      "source": {
        "discovery_source": "Agent Web Search",
        "source_level": "A",
        "discovery_only": false,
        "original_url": "https://semiconductor.samsung.com/news-events/tech-blog/breaking-ai-memory-limits-with-cxl-memory-pooling/",
        "published_at": "2026-07-06"
      },
      "direction_id": "memory_semantics"
    },
    {
      "candidate_id": "2c8529d07e0cfeba7586f7f4",
      "title": "DMG: A Scalable and Efficient Memory-Disaggregated Graph Processing System",
      "summary": "Traditional graph processing systems are built on monolithic servers, which couple a fixed ratio of compute and memory resources but often result in resource under-utilization in data centers. Although the disaggregated memory (DM) architecture has emerged to address this inefficiency, we identify that existing graph processing systems on DM remain highly impractical. They rely on unscalable architectures that fail to scale beyond a single memory node and a single compute node, and they require compute-side caches that are orders of magnitude larger than conventional practice in DM. To this end, this paper presents DMG, the first practical graph processing system on DM, which demonstrates superior system scalability and cache efficiency while delivering high performance. To improve efficiency of graph retrieval on DM, DMG proposes a DM-friendly graph store with retrieval optimizations. To mitigate costly update propagation, DMG presents an adaptive update coordinator that coordinates compute and memory nodes to perform update propagation with low overhead. To enable fast and effective load balancing, DMG employs a two-stage workload manager that includes a coarse-grained initial partitioning and a fine-grained runtime re-scheduling. Experimental results substantiate that compared with the state-of-the-art DM-based graph processing system, DMG can elastically scale up both compute and memory resources, delivering up to 4.9X better performance and accommodating graphs with ever-increasing sizes; meanwhile, it effectively tames the compute-side cache demands by up to 18.9X, positioning itself as a DM-ready solution in practice.",
      "rule_score": 81.6,
      "source": {
        "discovery_source": "arXiv",
        "source_level": "A",
        "discovery_only": false,
        "original_url": "https://arxiv.org/abs/2607.20881v1",
        "published_at": "2026-07-23T03:04:09Z"
      },
      "direction_id": "memory_semantics"
    },
    {
      "candidate_id": "9dbf30a720a6c247020ac301",
      "title": "REMOP: REmote-Memory-aware OPerator Optimization",
      "summary": "Remote and disaggregated memory tiers expand the effective memory capacity of analytical database engines, but they also reshape the cost structure of out-of-memory query processing. When an operator spills beyond local DRAM, moving pages to remote memory incurs both data-transfer time and a fixed round-trip latency per transfer. Classical operator analyses and buffer-allocation heuristics primarily target disk spilling by minimizing total I/O volume. Under remote memory, these strategies can be suboptimal because they may trigger excessive transfer rounds. We present REMOP, a remote-memory-aware operator optimization framework that uses transfer-round-aware intra-operator memory policies to improve out-of-memory execution under tight memory budgets. REMOP introduces the number of transfer rounds into the latency cost model and derives operator-specific buffer-partitioning strategies, instantiating the approach for blocked nested-loop join, external merge sort, and external hash join in DuckDB. Our evaluation on a two-node compute-memory testbed shows that REMOP reduces transfer rounds by up to 97% and operator runtime by up to 48% on spill-heavy microbenchmarks, and lowers the average runtime of spilling TPC-H and TPC-DS queries by 22.7% and 26.4% end-to-end.",
      "rule_score": 79.6,
      "source": {
        "discovery_source": "arXiv",
        "source_level": "A",
        "discovery_only": false,
        "original_url": "https://arxiv.org/abs/2606.19576v1",
        "published_at": "2026-06-17T20:28:47Z"
      },
      "direction_id": "memory_semantics"
    },
    {
      "candidate_id": "a9441fc3f770c513229819a9",
      "title": "Hash Table Design for RDMA:Challenges and Opportunities",
      "summary": "Hash tables complete the insertion, lookup, and deletion of a single key in constant time on average, and they are widely used in databases, key-value stores, and network systems. In the Internet of Things (IoT), the number of devices and the volume of sensed data keep growing, so the hash tables that store or index these data consume more and more memory. When a single server runs out of memory, the system can place part of the data in the memory of other nodes. One-sided operations in Remote Direct Memory Access (RDMA) let one machine read and write the memory of another machine directly, with low latency and high bandwidth, and are therefore widely used to build disaggregated memory systems. Deploying a hash table on RDMA-based remote memory exploits the memory of other nodes and thus relieves the capacity limit of a single server. However, this deployment raises three problems. First, one logical hash-table access may translate into one or more remote network accesses, and collision handling and probing further increase the number of RDMA requests. Second, because the remote CPU is bypassed, traditional concurrency control that relies on remote threads no longer applies directly. Third, the limited resources of RDMA network interface cards, such as queues, caches, memory registration, and atomic operations, impose new constraints on hash table structures. This paper focuses on hash table design for RDMA. We review existing work, distill the key challenges, and discuss promising optimization directions and coping strategies, aiming to provide a reference for designing remote hash tables in IoT big-data scenarios.",
      "rule_score": 79.6,
      "source": {
        "discovery_source": "arXiv",
        "source_level": "A",
        "discovery_only": false,
        "original_url": "https://arxiv.org/abs/2606.24073v3",
        "published_at": "2026-06-23T02:38:11Z"
      },
      "direction_id": "memory_semantics"
    },
    {
      "candidate_id": "b53ec01cfe3342252562d3b3",
      "title": "SHiPPO: Recurrent Memory with Transported Polynomial Projections",
      "summary": "HiPPO gives recurrent states memory semantics as coefficients of online polynomial projections, but in fixed channel coordinates. Modern selective SSMs, by contrast, rely on token-dependent control and channel interaction. We introduce SHiPPO (Sylvester HiPPO), a transported projection-memory prior that lifts HiPPO coefficient memories into a moving channel frame. For any fixed or realized right-transport path, SHiPPO transports the approximation family and channel metric together; conditional on that path, the state is ordinary HiPPO in a tied moving frame and follows Sylvester coefficient dynamics, preserving the left online-memory operator while adding right-action transport. For selective-SSM execution, we derive a restricted group-local realization with controller-compatible right actions, exponential-adjusted updates, exact block-affine scan, and recurrent decoding. We also give a simultaneous-reducibility criterion identifying when right transports collapse to static mixing plus independent scalar or blockwise banks. Controlled diagnostics show that larger current-token write rank improves ordinary prediction error but cannot recover order-sensitive changes to already-written memory; transported-memory variants recover this signal, which disappears when the transport pathway is removed. A finite-field associative-recall diagnostic with interleaved bindings, operations, and queries provides complementary autoregressive evidence while leaving the preferred right-action realization open. Taken together, these results support SHiPPO as a mechanistically grounded transported-memory prior, with evidence focused on memory mechanisms rather than broad sequence-modeling dominance.",
      "rule_score": 79.6,
      "source": {
        "discovery_source": "arXiv",
        "source_level": "A",
        "discovery_only": false,
        "original_url": "https://arxiv.org/abs/2607.03055v1",
        "published_at": "2026-07-03T07:44:44Z"
      },
      "direction_id": "memory_semantics"
    },
    {
      "candidate_id": "d699dc960dfe250eb132334e",
      "title": "Evaluating Gemma4 Models as AI Teaching Assistants for Introductory Parallel Programming: A DataRaceBench Study",
      "summary": "Debugging data races is a major challenge for students learning parallel programming due to the non-deterministic nature of concurrent execution and the complexity of shared-memory semantics. Recent advances in Large Language Models (LLMs) suggest that they could serve as AI teaching assistants, but the capabilities of lower-cost open-weight models for parallel debugging remain unclear. In this paper, we evaluate two Gemma4 open-weight models, Gemma4-E4B and Gemma4-31B, on their ability to identify, explain, and repair data races in OpenMP programs from the DataRaceBench benchmark suite. We also investigate whether contextual hints, including ThreadSanitizer (TSan) reports and model-generated explanations, improve repair quality. Our results show that Gemma4-E4B correctly explained 82 of 104 race-condition programs and successfully repaired 73, while Gemma4-31B achieved 100 correct explanations and 98 successful repairs. Surprisingly, additional context did not consistently improve repair effectiveness and sometimes reduced performance. These findings suggest that open-weight LLMs can provide valuable support for student self-debugging, with larger models offering near-complete coverage of the benchmark suite.",
